/* Original navigation UI and mathematical diagrams. Third-party simulations are linked, not embedded. */
'use strict';
let catalog;
let activeDemo=null;
const C=window.ResourceCompare;
const main=document.getElementById('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const href=(path,params={})=>'#/'+path+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
const external=(url,label,cls='')=>url.startsWith('#/')?`<a class="${cls}" href="${esc(url)}">${esc(label.replace(/原站/g,'本站'))}</a>`:`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}<span aria-hidden="true"> ↗</span><span class="sr-only">（新标签页）</span></a>`;
const topic=id=>catalog.topics.find(t=>t.id===id);
const subject=id=>catalog.subjects.find(s=>s.id===id);
const subjectCount=id=>catalog.resources.filter(r=>r.subjects.includes(id)).length;
const count=(id,subjectId='')=>catalog.resources.filter(r=>r.topics.includes(id)&&(!subjectId||r.subjects.includes(subjectId))).length;
function badge(r){const s=r.verification.interaction;return `<span class="status ${s==='tested'?'':s==='partial'?'partial':'docs'}">${s==='tested'?'已实际操作':s==='partial'?'操作部分核验':'已读说明 · 未实操'}</span>`;}
function math(tex){if(!window.katex)return `<code>${esc(tex)}</code>`;try{return katex.renderToString(tex,{throwOnError:true,displayMode:true,trust:false,output:'htmlAndMathml'});}catch(e){console.error('Formula error',tex,e);return `<code class="math-error">${esc(tex)}</code>`;}}
function tags(r){return `<div class="tags">${r.topics.map(id=>`<a class="tag" href="${href('resources',{topic:id})}">${esc(topic(id)?.name||id)}</a>`).join('')}</div>`;}
function points(fn,x0=20,x1=380,y0=70,amp=36){return Array.from({length:121},(_,i)=>{const x=i/120;return `${i?'L':'M'}${(x0+x*(x1-x0)).toFixed(1)},${(y0-amp*fn(x)).toFixed(1)}`;}).join(' ');}
function diagram(kind='wave',large=false){
 if(kind==='chain'){
  return '<svg viewBox="0 0 400 140" role="img" aria-label="本站原创等压位移与 T、V 两个坐标分量的概念图"><path d="M75 115H330M95 120V20" fill="none" stroke="var(--line)"/><path d="M130 95H275" stroke="var(--orange)" stroke-width="3"/><path d="M130 95V35" stroke="var(--teal)" stroke-width="3"/><path d="M130 95L275 35" stroke="var(--accent)" stroke-width="3"/><path d="M130 35H275V95" fill="none" stroke="var(--muted)" stroke-dasharray="4 4"/><circle cx="130" cy="95" r="4" fill="var(--ink)"/><circle cx="275" cy="35" r="4" fill="var(--accent)"/><text x="113" y="108" fill="var(--ink)" font-size="14">A</text><text x="280" y="28" fill="var(--ink)" font-size="14">D</text><text x="334" y="119" fill="var(--muted)" font-size="14">T</text><text x="85" y="18" fill="var(--muted)" font-size="14">V</text></svg>';
 }
 if(kind==='constraint'){
  const project=(u,v,w)=>[200+58*(u-v),122-20*w-7*(u+v)];
  const path=points=>points.map((p,i)=>(i?'L':'M')+project(...p).join(',')).join(' ');
  let mesh='';for(let i=0;i<=6;i++){const s=.25+1.75*i/6;for(const along of [0,1])mesh+=`<path d="${path(Array.from({length:25},(_,j)=>{const t=.25+1.75*j/24;return along?[s,t,s*t]:[t,s,t*s];}))}" fill="none" stroke="#88a6b8" stroke-width=".8"/>`;}
  const curve=path(Array.from({length:41},(_,i)=>{const u=.5+1.5*i/40;return [u,1/u,1];}));
  return `<svg viewBox="0 0 400 140" role="img" aria-label="本站原创约束曲面 uv = w 的概念图，蓝线为固定 w 的截线"><path d="M84 108L200 122L316 108M200 122V30" fill="none" stroke="#bfd0dd"/>${mesh}<path d="${curve}" fill="none" stroke="#166eaa" stroke-width="3"/><circle cx="200" cy="88" r="4" fill="#172a40"/><text x="210" y="84" fill="#172a40" font-size="14">P</text><text x="322" y="110" fill="#52677b" font-size="14">u</text><text x="70" y="110" fill="#52677b" font-size="14">v</text><text x="208" y="28" fill="#52677b" font-size="14">w</text></svg>`;
 }

 let marks='';const line=(fn,c,opacity=1,dash='')=>`<path d="${points(fn)}" stroke="${c}" opacity="${opacity}" stroke-width="2.5" fill="none" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
 if(kind==='heat'){marks=line(x=>Math.cos(4*Math.PI*x),'#8babc0',.6,'4 4')+line(x=>.60*Math.cos(4*Math.PI*x),'#178893')+line(x=>.20*Math.cos(4*Math.PI*x),'#356c9d');}
 else if(kind==='fourier'){marks=line(x=>.7*Math.sign(Math.sin(2*Math.PI*x)),'#98aabb',.7)+line(x=>.8*(Math.sin(2*Math.PI*x)+Math.sin(6*Math.PI*x)/3+Math.sin(10*Math.PI*x)/5),'#148691');}
 else if(kind==='membrane'||kind==='bessel'){for(let j=0;j<11;j++){const y=25+j*8;marks+=`<path d="${points(x=>Math.sin(Math.PI*x)*Math.cos(j/10*Math.PI*2),70,330,y,14)}" stroke="#277b91" stroke-width="1.5" fill="none" opacity="${.4+j*.04}"/>`;}}
 else if(kind==='complex'){for(let i=0;i<6;i++){marks+=`<path d="M${50+i*17} 26v90 M50 ${26+i*18}h85" stroke="#597f9c" stroke-width="1"/><path d="M${245+i*15} 22 Q${210+i*14} 68 ${248+i*16} 117 M235 ${26+i*18} Q288 ${48+i*12} 346 ${26+i*18}" fill="none" stroke="#118c90" stroke-width="1"/>`;}marks+='<text x="176" y="77" fill="#537288" font-size="20">→</text>';}
 else if(kind==='potential'){for(let i=1;i<5;i++){marks+=`<ellipse cx="200" cy="70" rx="${i*31}" ry="${i*12}" stroke="#4b8b9d" fill="none" opacity=".7"/>`;}marks+='<circle cx="200" cy="70" r="6" fill="#b87842"/>';}
 else if(kind==='advection'){marks=line(x=>Math.exp(-80*(x-.26)**2),'#759aaf',.6,'4 4')+line(x=>.72*Math.exp(-40*(x-.66)**2),'#12818e');}
 else{marks=line(x=>Math.sin(2*Math.PI*x),'#98b3c3',.6,'4 4')+line(x=>Math.sin(4*Math.PI*x),'#188895')+line(x=>.45*Math.sin(6*Math.PI*x),'#658aa7',.45);}
 return `<svg viewBox="0 0 400 140" role="img" aria-label="${esc(kind==='heat'?'相同空间频率的曲线随时间降低幅度':kind==='fourier'?'方波与有限项傅里叶和':kind==='complex'?'复平面网格映射':kind==='potential'?'等值线概念':kind==='advection'?'移动并展宽的函数图像':'空间模态概念')}：本站原创示意，非原站截图"><path d="M20 70H380" stroke="#cbdce5" stroke-width="1"/>${marks}${large?'<text x="380" y="88" fill="#658091" font-size="13">x</text>':''}</svg>`;
}
function card(r){return `<article class="resource-card" data-resource="${esc(r.id)}"><div class="card-visual">${diagram(r.visual)}<span class="visual-label">${r.kind==='local'?'本站原创 · 概念示意':'概念示意 · 原演示见链接'}</span></div><div class="card-content"><div class="card-top"><span>${esc(r.source)} · ${esc(r.format)}</span>${badge(r)}</div><h3><a href="${href('resource/'+r.id)}">${esc(r.title)}</a></h3><p>${esc(r.question)}</p>${tags({...r,topics:r.topics.slice(0,3)})}<div class="card-bottom"><span>${esc(r.depth)} · ${esc(r.language)}</span>${external(r.url,r.kind==='local'?'打开站内演示':'打开演示')}</div>${C.button(r)}</div></article>`;}
function searchForm(q=''){return `<form class="search-wrap" id="search-form" role="search"><label class="sr-only" for="query">搜索知识点或资源</label><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="query" name="q" type="search" autocomplete="off" placeholder="搜索：等压偏导、驻波、静电势…" value="${esc(q)}"><button type="submit">搜索</button></form>`;}
function home(){return resourceList();}
function readParams(){return new URLSearchParams((location.hash.split('?')[1]||''));}
function normalize(s){return s.normalize('NFKC').toLowerCase().replace(/[\s／/·—–-]/g,'');}
function matchResources(p){const terms=(p.get('q')||'').trim().toLowerCase().split(/\s+/).filter(Boolean);return catalog.resources.filter(r=>{
 const ids=r.topics;const topicWords=ids.flatMap(id=>{const t=topic(id);return t?[t.name,...t.aliases]:[];});
 const subjectWords=r.subjects.flatMap(id=>{const s=subject(id);return s?[s.name,...s.aliases]:[];});
 const text=normalize([r.title,r.originalName,r.question,r.guide,r.source,...r.aliases,...topicWords,...subjectWords].join(' '));
 return terms.every(q=>text.includes(normalize(q)))&&(!p.get('subject')||r.subjects.includes(p.get('subject')))&&(!p.get('topic')||ids.includes(p.get('topic')))&&(!p.get('source')||r.source===p.get('source'))&&(!p.get('depth')||r.depth===p.get('depth'))&&(!p.get('status')||r.verification.interaction===p.get('status'));
 });}
function select(name,label,values,p){return `<label>${label}<select name="${name}" aria-label="${label}"><option value="">全部</option>${values.map(v=>{const val=typeof v==='string'?v:v[0],txt=typeof v==='string'?v:v[1];return `<option value="${esc(val)}" ${p.get(name)===val?'selected':''}>${esc(txt)}</option>`;}).join('')}</select></label>`;}
function resultsHTML(p){
 const filtered=matchResources(p),hasFilters=['q','subject','topic','source','depth','status'].some(key=>p.has(key));
 const selectedSubject=subject(p.get('subject')),emptySubject=selectedSubject&&subjectCount(selectedSubject.id)===0;
 const labels=[selectedSubject?.name,topic(p.get('topic'))?.name].filter(Boolean);
 return `<div class="result-line" role="status" aria-live="polite"><span><strong>${filtered.length}</strong> 个演示${labels.length?' · '+esc(labels.join(' / ')):''}</span>${hasFilters?'<button class="text-button" data-clear>清除筛选</button>':'<span>本站原创与精选外部资源</span>'}</div>${filtered.length?`<div class="cards">${filtered.map(card).join('')}</div>`:`<div class="empty"><h2>${emptySubject?esc(selectedSubject.name)+'暂未收录演示':'没有匹配的演示'}</h2><p>${emptySubject?'可先浏览其他学科；新增资源会归入相应分类。':'试试其他关键词，或清除筛选条件。'}</p><button class="button outline" data-clear>浏览全部演示</button></div>`}`;
}
function resourceList(){
 const p=readParams(),params=Object.fromEntries(p),subjectId=p.get('subject')||'';
 const allSubjects={...params};delete allSubjects.subject;delete allSubjects.topic;
 const allTopics={...params};delete allTopics.topic;
 const advanced=['source','depth','status'].some(key=>p.has(key));
 return `<header class="page-heading catalog-heading"><div class="eyebrow">交互演示资源库</div><h1>找到你想看清的物理问题</h1><p>按学科、知识点或关键词，直接找到可操作的演示。</p>${searchForm(p.get('q')||'')}</header><nav class="subject-nav" aria-label="按学科筛选"><a data-subject="" href="${href('resources',allSubjects)}" class="${!subjectId?'active':''}" ${!subjectId?'aria-current="true"':''}>全部<span>${catalog.resources.length}</span></a>${catalog.subjects.map(s=>{const next={...allSubjects,subject:s.id};return `<a data-subject="${esc(s.id)}" href="${href('resources',next)}" class="${subjectId===s.id?'active':''}" ${subjectId===s.id?'aria-current="true"':''}>${esc(s.name)}<span>${subjectCount(s.id)}</span></a>`;}).join('')}</nav><div class="catalog-layout"><aside class="topic-sidebar" aria-label="按知识点筛选"><a data-topic="" href="${href('resources',allTopics)}" class="${!p.get('topic')?'active':''}">全部知识点</a>${['method','application'].map(kind=>`<h2>${kind==='method'?'数学工具':'物理问题'}</h2>${catalog.topics.filter(t=>t.kind===kind&&count(t.id,subjectId)).map(t=>`<a href="${href('resources',{...params,topic:t.id})}" data-topic="${t.id}" class="${p.get('topic')===t.id?'active':''}" ${p.get('topic')===t.id?'aria-current="true"':''}>${esc(t.name)} <span>${count(t.id,subjectId)}</span></a>`).join('')}`).join('')}</aside><section class="catalog-main" aria-label="资源搜索结果"><details class="filter-disclosure" ${advanced?'open':''}><summary>更多筛选${advanced?' · 已设置':''}</summary><div class="filters">${select('source','来源',[...new Set(catalog.resources.map(r=>r.source))],p)}${select('depth','深度',['入门','课程核心','进阶'],p)}${select('status','核验',[['tested','已实际操作'],['partial','操作部分核验'],['docs','已读说明 · 未实操']],p)}</div></details><div id="results">${resultsHTML(p)}</div></section></div>`;
}
function operationCard(r){const o=r.operation;if(!o)return '';return `<section class="operation-card" aria-labelledby="operation-title"><div class="section-top"><div><div class="eyebrow">可带到原站使用</div><h2 id="operation-title">操作卡 · 从同一起点开始</h2></div><button class="button outline" type="button" data-copy-card="${esc(r.id)}">复制操作卡</button></div><p>${esc(o.entry)}</p><ol class="setup-list">${o.startingState.map(v=>`<li>${esc(v)}</li>`).join('')}</ol><details class="control-dictionary"><summary>对照原站控件的中英文</summary><dl>${o.controls.map(c=>`<div><dt>${esc(c.name)}<span>${esc(c.meaning)}</span></dt><dd>${esc(c.usage)}<small>${esc(c.evidence)}</small></dd></div>`).join('')}</dl></details><div class="reset-grid"><div><h3>重新开始这次比较</h3><p>${esc(o.restart)}</p></div><div><h3>恢复起点设置</h3><p>${esc(o.restoreDefault)}</p>${external(r.url,'重新打开原始入口 ↗')}</div></div><p class="tested-range"><strong>已核验的范围：</strong>${esc(o.testedRange)}</p><details class="operation-help"><summary>画面不对时，先检查这里</summary>${o.troubleshooting.map(t=>`<div><h3>${esc(t.symptom)}</h3><p>${esc(t.action)}</p></div>`).join('')}</details><p class="proof-note">操作卡整理：${esc(o.reviewedAt)}。${esc(o.evidenceNote)}${o.guideSource?' '+external(o.guideSource,'时间控制原站说明'):''}</p><details class="local-report"><summary>记录链接失效或步骤不符</summary><p class="small muted">在本页生成可编辑的问题记录，补充现象后可自行复制给维护者。内容不会自动发送，离开本页前请保存。</p><button class="button outline" type="button" data-issue-template="${esc(r.id)}">生成问题记录</button><div id="issue-draft" hidden><label for="issue-text">问题记录（可以修改）</label><textarea id="issue-text" rows="11"></textarea><button type="button" class="text-button" data-select-issue>全选问题记录</button><p class="small muted">全选后用 Ctrl+C 或系统复制菜单保存。</p></div></details><p id="copy-status" class="small" role="status" aria-live="polite"></p><div id="copy-fallback" hidden><label for="copy-text">操作卡纯文本（含原站链接和三个任务，可手动复制）</label><textarea id="copy-text" readonly rows="9"></textarea></div></section>`;}
function operationText(r){const o=r.operation;return [r.title,r.originalName,`来源：${r.source} · ${r.author||'署名见原站'}`,r.url,`核验：${r.verification.date}；${r.verification.environment}`,o.entry,'【起点】',...o.startingState.map((v,i)=>`${i+1}. ${v}`),'【控件】',...o.controls.map(c=>`${c.name}（${c.meaning}）：${c.usage}〔${c.evidence}〕`),'【三个观察任务】',...r.steps.map((v,i)=>`${i+1}. ${v.title}
操作：${v.action}
观察：${v.observe}
范围：${v.evidence}`),'【重新开始】',o.restart,'【恢复起点】',o.restoreDefault,'【已核验范围】',o.testedRange,'【排查】',...o.troubleshooting.map(t=>`${t.symptom}：${t.action}`),o.evidenceNote].join('\n\n');}
function bindOperation(){
 const copy=document.querySelector('[data-copy-card]');
 if(copy)copy.addEventListener('click',async()=>{
  const r=catalog.resources.find(x=>x.id===copy.dataset.copyCard);const value=operationText(r);
  document.getElementById('copy-fallback').hidden=false;const field=document.getElementById('copy-text');field.value=value;field.focus();field.select();
  const status=document.getElementById('copy-status');status.textContent='操作卡已展开并选中，可用 Ctrl+C 或系统复制菜单。';
  try{await navigator.clipboard.writeText(value);if(copy.isConnected)status.textContent='已请求复制。若粘贴无内容，可在下方手动复制完整操作卡。';}catch{}
 });
 const issue=document.querySelector('[data-issue-template]');
 if(issue)issue.addEventListener('click',()=>{
  const r=catalog.resources.find(x=>x.id===issue.dataset.issueTemplate);
  const field=document.getElementById('issue-text');document.getElementById('issue-draft').hidden=false;
  if(!field.value)field.value=`物理可视化 · 问题记录
资源：${r.title}
资源 ID：${r.id}
原站：${r.url}
原核验日期：${r.verification.date}
记录时间：${new Date().toISOString()}

问题类型（链接失效 / 步骤不符 / 其他）：
设备与浏览器：
实际停在哪一步：
看到了什么：
期望看到什么：

本记录只在本页生成，未自动发送。`;
  field.focus();document.getElementById('copy-status').textContent='问题记录已生成，可以修改。离开前请自行复制保存。';
 });
 document.querySelector('[data-select-issue]')?.addEventListener('click',()=>{const field=document.getElementById('issue-text');field.focus();field.select();});
}
function resourceDetail(id){const r=catalog.resources.find(x=>x.id===id);if(!r)return notFound();if(r.kind==='local'){const demo=window.SiteDemos?.[r.module];if(!demo)return notFound();activeDemo=demo;return demo.page(r,{esc,math,compare:C.button(r)});}return `<div class="breadcrumbs"><a href="${href('resources')}">资源目录</a><span>/</span><span>${esc(r.source)}</span></div><header class="detail-head"><div class="eyebrow">${esc(r.format)} · ${esc(r.depth)}</div><h1>${esc(r.title)}</h1><p class="original-name">${esc(r.originalName)}</p>${tags(r)}${C.button(r)}<div class="mobile-entry">${external(r.url,'打开原站演示','button')}<span>${esc(r.source)} · ${esc(r.language)}</span>${badge(r)}</div></header><div class="detail-layout"><article class="article"><section class="question-box"><div class="eyebrow">带着这个问题打开演示</div><p>${esc(r.question)}</p></section><section class="article-section"><h2>演示看什么</h2><p>${esc(r.guide)}</p><div class="reading-key"><strong>坐标、函数值与颜色</strong><p>${esc(r.reading)}</p></div><div class="formula" tabindex="0" role="group" aria-label="公式，较长时可横向滚动">${math(r.formula)}</div><p class="symbols">${esc(r.symbols)}</p></section>${operationCard(r)}<section class="article-section"><h2>观察建议</h2><p class="proof-note">${r.verification.interaction==='docs'?'以下步骤依据原站操作说明核对，本次未完成界面实操；效果是待观察的问题。':'每步标明核验范围。观察任务是学习目标，不是精度测试结论。'}</p><ol class="tasks">${r.steps.map(s=>`<li><h3>${esc(s.title)}<span class="task-state">${esc(s.evidence)}</span></h3><p>${esc(s.action)}</p><p class="observe"><strong>观察：</strong>${esc(s.observe)}</p></li>`).join('')}</ol></section><section class="article-section"><h2>现象解释</h2><p>${esc(r.think.question)}</p><details><summary>展开解释与推理</summary><div class="explanation"><p>${esc(r.think.answer)}</p>${r.think.formula?`<div class="formula" tabindex="0" role="group" aria-label="公式，较长时可横向滚动">${math(r.think.formula)}</div>`:''}</div></details></section><section class="article-section"><h2>模型边界与易误读处</h2><ul class="prose-list">${r.cautions.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>${r.errata?`<div class="caution"><strong>原站公式核对：</strong>${esc(r.errata)}</div>`:''}</section><section class="article-section"><h2>与教材怎样对应</h2><p class="small muted">这是按知识点建立的本站映射，不是教材官方配套，也不代表覆盖该章。</p>${(r.mappings||[]).map(m=>`<p class="mapping-list"><strong>${esc(m.book)}</strong><br>${esc(m.location)} · <a href="${href('about',{section:'books'})}">目录依据见来源说明</a></p>`).join('')||'<p>本条仅作通用知识点关联，尚未加入具体章节映射。</p>'}</section><div class="button-row"><a class="button outline" href="${href('resources')}">继续浏览资源</a></div></article><aside class="source-panel" aria-label="原站入口与核验信息"><h2>进入原作者的演示</h2>${external(r.url,'打开原站演示','button')}${badge(r)}<dl><dt>来源</dt><dd>${esc(r.source)}</dd><dt>作者 / 团队</dt><dd>${esc(r.author||'原站未明确署名')}</dd><dt>语言</dt><dd>${esc(r.language)}</dd><dt>先修知识</dt><dd>${esc(r.prerequisites)}</dd><dt>可调整的量</dt><dd>${esc(r.controls)}</dd><dt>核验日期</dt><dd>${esc(r.verification.date)}</dd></dl><hr><div class="source-links">${external(r.descriptionUrl,'原站说明')}${external(r.backupUrl,'原站目录 / 备用入口')}</div><p class="proof-note">${esc(r.verification.note)}</p><p class="fallback">若原站打不开或画面空白，请先读说明或从原站目录重新查找。本页不检测原站实时可用性；本站导读仍可阅读。${r.verification.availability==='failed'?' 本次模拟运行未成功，详见核验记录。':''}</p><a class="small" href="${href('about')}">核验范围与使用条件</a></aside></div>`;}
function about(){return `<div class="about-layout"><div class="eyebrow">关于资源</div><h1>物理可视化</h1><section class="article-section"><h2>带着问题，找到好演示</h2><p>这里收集可以直接操作的物理可视化，按理论力学、电动力学、量子力学、热力学与统计物理组织，并保留通用数学工具。可从学科、知识点或关键词进入；同一演示可以关联多个分类。</p><p>本站原创演示在页面中操作，外部资源直接链接到原作者的网站。每个条目提供读图说明、可调量和来源，方便判断是否适合当前问题。</p></section><section class="article-section"><h2>怎样选择资源</h2><p>优先收录围绕明确物理问题、能改变条件并观察结果的交互演示。条目注明模型条件、作者与核验日期；卡片上的图形是本站原创概念示意。</p><ul class="prose-list"><li><strong>已实际操作：</strong>操作过主要控件，并核对画面与说明。</li><li><strong>操作部分核验：</strong>部分控件或步骤已确认。</li><li><strong>已读说明 · 未实操：</strong>已核对文档，尚未完成运行核验。</li></ul><p class="small muted">核验范围以各条目为准。外部资源的记录保留原日期，运行情况可能随原站更新而变化。</p></section><section class="article-section"><h2>资源来源</h2>${catalog.sources.filter(s=>catalog.resources.some(r=>r.source===s.name.split(' · ')[0])).map(s=>`<div class="book"><h3>${esc(s.name.split(' · ')[0])}</h3><p>${esc(s.name.startsWith('VisualPDE')?'由 Benjamin Walker、Adam Townsend、Andrew Krause 编写维护，提供初始条件、边界条件和参数的交互演示。':'Paul Falstad 的模态、傅里叶与复映射演示；具体作者署名见各条目。')}</p><div class="book-links">${external(s.url,'原站入口')}${s.license?external(s.license,'使用条件 / 许可说明'):''}</div></div>`).join('')}<p class="small muted">外部演示版权归原作者。本站提供链接及原创中文说明；公式使用本地 KaTeX 排版。</p></section><details class="article-section" id="books"><summary>教材版本与映射依据</summary><p class="small muted">采用通用知识点分类，不沿用某本书的整套章节顺序。下面只列本次能够核实的版本和映射范围，不提供未经核实的书页码。</p>${catalog.books.map(b=>`<div class="book"><h3>${esc(b.title)}</h3><p class="book-meta">${esc(b.authors)} · ${esc(b.publisher)}<br>${esc(b.edition)} · ISBN ${esc(b.isbn)}</p><p>${esc(b.evidence)}</p><p class="mapping-list">${esc(b.mapping)}</p><div class="book-links">${b.links.map(l=>external(l.url,esc(l.label))).join('')}</div></div>`).join('')}</details></div>`;}
function notFound(){return `<div class="empty"><h1>这个页面暂时不存在</h1><p>链接可能已修改，请从目录重新选择资源。</p><a class="button" href="${href('resources')}">返回资源目录</a></div>`;}
function bind(){
 bindOperation();C.update();const form=document.getElementById('search-form');if(!form)return;
 const updateLinks=p=>{const params=Object.fromEntries(p);document.querySelectorAll('[data-topic]').forEach(a=>{const next={...params};if(a.dataset.topic)next.topic=a.dataset.topic;else delete next.topic;a.href=href('resources',next);});document.querySelectorAll('[data-subject]').forEach(a=>{const next={...params};delete next.topic;if(a.dataset.subject)next.subject=a.dataset.subject;else delete next.subject;a.href=href('resources',next);});};
 form.addEventListener('submit',e=>{e.preventDefault();const p=Object.fromEntries(readParams()),q=new FormData(form).get('q').trim();if(q)p.q=q;else delete p.q;location.hash=href('resources',p);});
 document.getElementById('query').addEventListener('input',e=>{const p=readParams();if(e.target.value.trim())p.set('q',e.target.value.trim());else p.delete('q');history.replaceState(null,'',href('resources',Object.fromEntries(p)));document.getElementById('results').innerHTML=resultsHTML(p);C.update();updateLinks(readParams());});
 document.querySelectorAll('.filters select').forEach(el=>el.addEventListener('change',()=>{const p=Object.fromEntries(readParams());if(el.value)p[el.name]=el.value;else delete p[el.name];location.hash=href('resources',p);}));
}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();main.scrollIntoView();return;}if(e.target.closest('[data-clear]')){if(location.hash==='#/resources'){render();}else location.hash='#/resources';}const s=e.target.closest('[data-scroll]');if(s){e.preventDefault();document.getElementById(s.dataset.scroll)?.scrollIntoView();}});
function render(){if(!catalog)return;const path=(location.hash.replace(/^#\/?/,'').split('?')[0]||'');if(path==='route'){location.replace(href('resources'));return;}const section=path.split('/')[0];C.sync(readParams(),section);window.MathPhysLab?.unmount();activeDemo?.unmount();activeDemo=null;main.innerHTML=path===''?home():path==='resources'?resourceList():path==='compare'?C.page():path.startsWith('resource/')?resourceDetail(path.slice(9)):path==='lab'?window.MathPhysLab.page():path==='about'?about():notFound();document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(['resource','compare',''].includes(section)?'resources':section);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const title=main.querySelector('h1')?.textContent||'物理可视化';document.title=(path===''||path==='resources')?'物理可视化 · 交互演示资源库':(title==='物理可视化'?title:title+' · 物理可视化');bind();if(path==='lab')window.MathPhysLab.mount();activeDemo?.mount();window.scrollTo(0,0);main.focus({preventScroll:true});if(path==='about'&&readParams().get('section')==='books'){const books=document.getElementById('books');books.open=true;books.scrollIntoView();}}
window.addEventListener('hashchange',render);
fetch('catalog.json').then(r=>{if(!r.ok)throw Error('目录加载失败');return r.json();}).then(data=>{catalog=data;C.configure({catalog,esc,external,badge,tags});render();}).catch(()=>{main.innerHTML='<div class="empty"><h1>资源目录未能加载</h1><p>请通过项目的本地预览服务打开网站，并检查 catalog.json 是否存在。</p><button class="button" onclick="location.reload()">重新加载</button></div>';});
